scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 3. 브라우저에서 크기를 줄여서 autoFit 이 적용되는지 확인한다.
    //3. Reduce the size in the browser to see if autoFit is applied.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#group1').css('width', '50%')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 
    //
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_scrollX_div').css('height') != '0px'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
